-- ═══════════════════════════════════════════════════════════════════════════════════════════
-- CBT online exam — complete database setup (generated by tools/buildCbtSetup.mjs; do not edit by hand).
-- Paste ALL of this into Supabase → SQL editor → Run. It works on an empty database and on top of any earlier
-- partial run, and can be run again after an update. Contents, in order:
--   20261034_cbt_online_exam.sql
--   20261035_cbt_erp_lookup.sql
--   20261036_cbt_lock_answers.sql
--   20261037_cbt_hardening.sql
--   20261038_cbt_integrity.sql
--   20261039_cbt_gcc_identity.sql
--   20261040_cbt_lookup_father.sql
-- Needs the Students module's tables (public.students) and the helper public.qbank_is_staff() to exist already.
-- ═══════════════════════════════════════════════════════════════════════════════════════════

-- Newer function versions are dropped first so older scripts below can be replayed without a name clash;
-- the later scripts then recreate the final versions.
drop function if exists public.cbt_start(text, text, text, text, text);
drop function if exists public.cbt_lookup(text, text, text, text);
drop function if exists public.cbt_resume(text, text, text);
drop function if exists public.cbt_submit(text, text, jsonb, jsonb, int, text);
drop function if exists public.cbt_save(text, text, jsonb, jsonb, int, text, int, text);

-- ───── 20261034_cbt_online_exam.sql ─────
-- ============================================================================
-- CBT Exam: take the exam from anywhere (online exam link)
-- ============================================================================
-- A test built in CBT Exam can be published as a link (…/exam?t=<id>) that candidates open on their own
-- phone or computer. Everything a candidate can do goes through the functions below, because the tables
-- are private:
--   • the paper (questions, pictures) is handed out only to someone who has started an attempt, and
--     never contains the answers — the answer key lives in cbt_keys, which only staff can read
--   • the clock is the server's: an attempt has a start time and a deadline, answers saved after the
--     deadline (plus a short grace for a slow connection) are ignored
--   • the score is worked out here, from the key, when the attempt is submitted
--   • one attempt per roll number; a candidate resumes with a secret token kept in their browser
-- Staff (qbank_is_staff) can read and change everything, so results show on any office computer.
--
-- REQUIRES 20260925_qbank_rls.sql (qbank_is_staff). Safe to run more than once.
-- ============================================================================

do $$
begin
  if to_regprocedure('public.qbank_is_staff()') is null then
    raise exception 'Run 20260925_qbank_rls.sql first.';
  end if;
end $$;

create table if not exists public.cbt_tests (
  id            text primary key,
  name          text not null,
  duration_min  numeric not null check (duration_min > 0),
  marking       jsonb not null default '{"correct":1,"wrong":0}'::jsonb,
  instructions  text,
  show_result   boolean not null default true,
  show_answers  boolean not null default true,
  sections      jsonb not null,                       -- questions WITHOUT answers
  status        text not null default 'live' check (status in ('draft', 'live', 'closed')),
  access_code   text,                                 -- empty = no code needed
  opens_at      timestamptz,
  closes_at     timestamptz,
  grace_seconds int not null default 20,              -- slack for a slow connection when submitting
  created_by    text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table if not exists public.cbt_keys (
  test_id text primary key references public.cbt_tests (id) on delete cascade,
  answers jsonb not null default '{}'::jsonb          -- { "1": "A", "2": "C", … }
);

create table if not exists public.cbt_attempts (
  id             text primary key default gen_random_uuid()::text,
  test_id        text not null references public.cbt_tests (id) on delete cascade,
  candidate_name text not null,
  roll           text not null,
  roll_key       text generated always as (lower(btrim(roll))) stored,
  phone          text,
  token          text not null,
  started_at     timestamptz not null default now(),
  saved_at       timestamptz,
  submitted_at   timestamptz,
  state          text not null default 'inprogress' check (state in ('inprogress', 'submitted')),
  auto_submitted boolean not null default false,
  answers        jsonb not null default '{}'::jsonb,
  marked         jsonb not null default '{}'::jsonb,
  current_no     int,
  lang           text,
  switches       int not null default 0,
  score          jsonb,
  unique (test_id, roll_key)
);
create index if not exists cbt_attempts_test_idx on public.cbt_attempts (test_id);

alter table public.cbt_tests    enable row level security;
alter table public.cbt_keys     enable row level security;
alter table public.cbt_attempts enable row level security;

drop policy if exists cbt_tests_staff    on public.cbt_tests;
drop policy if exists cbt_keys_staff     on public.cbt_keys;
drop policy if exists cbt_attempts_staff on public.cbt_attempts;
create policy cbt_tests_staff    on public.cbt_tests    for all to authenticated using (public.qbank_is_staff()) with check (public.qbank_is_staff());
create policy cbt_keys_staff     on public.cbt_keys     for all to authenticated using (public.qbank_is_staff()) with check (public.qbank_is_staff());
create policy cbt_attempts_staff on public.cbt_attempts for all to authenticated using (public.qbank_is_staff()) with check (public.qbank_is_staff());

-- ── scoring (same shape as the app's grade()) ────────────────────────────────
create or replace function public.cbt_grade(p_sections jsonb, p_marking jsonb, p_key jsonb, p_answers jsonb)
returns jsonb
language plpgsql
immutable
as $$
declare
  plus numeric := coalesce((p_marking ->> 'correct')::numeric, 1);
  minus numeric := coalesce((p_marking ->> 'wrong')::numeric, 0);
  s jsonb; q jsonb; no text; given text; k text;
  secs jsonb := '[]'::jsonb;
  t_total int := 0; t_att int := 0; t_cor int := 0; t_wr int := 0; t_uns int := 0; t_marks numeric := 0; t_max numeric := 0;
  total int; att int; cor int; wr int; uns int; marks numeric; mx numeric;
begin
  for s in select value from jsonb_array_elements(coalesce(p_sections, '[]'::jsonb)) loop
    total := 0; att := 0; cor := 0; wr := 0; uns := 0; marks := 0; mx := 0;
    for q in select value from jsonb_array_elements(coalesce(s -> 'questions', '[]'::jsonb)) loop
      no := q ->> 'no'; given := nullif(p_answers ->> no, ''); k := nullif(p_key ->> no, '');
      total := total + 1;
      if given is not null then att := att + 1; end if;
      if k is null then uns := uns + 1; continue; end if;
      mx := mx + plus;
      if given = k then cor := cor + 1; marks := marks + plus;
      elsif given is not null then wr := wr + 1; marks := marks - minus; end if;
    end loop;
    secs := secs || jsonb_build_object('id', s ->> 'id', 'label', s ->> 'label', 'title', s ->> 'title', 'total', total, 'attempted', att,
      'correct', cor, 'wrong', wr, 'unscored', uns, 'marks', round(marks, 2), 'max', round(mx, 2));
    t_total := t_total + total; t_att := t_att + att; t_cor := t_cor + cor; t_wr := t_wr + wr; t_uns := t_uns + uns; t_marks := t_marks + marks; t_max := t_max + mx;
  end loop;
  return jsonb_build_object(
    'marks', round(t_marks, 2), 'max', round(t_max, 2), 'total', t_total, 'attempted', t_att, 'correct', t_cor, 'wrong', t_wr,
    'unscored', t_uns, 'skipped', t_total - t_att,
    'accuracy', case when t_att > 0 then round(t_cor::numeric / t_att * 100, 1) else 0 end,
    'percent', case when t_max > 0 then round(t_marks / t_max * 100, 1) else null end,
    'complete', t_uns = 0, 'sections', secs);
end $$;

-- ── helpers ──────────────────────────────────────────────────────────────────
create or replace function public.cbt_deadline(a public.cbt_attempts, t public.cbt_tests)
returns timestamptz language sql immutable as $$
  select a.started_at + (t.duration_min * interval '1 minute')
$$;

create or replace function public.cbt_paper(t public.cbt_tests)
returns jsonb language sql immutable as $$
  select jsonb_build_object('id', t.id, 'name', t.name, 'durationMin', t.duration_min, 'marking', t.marking,
    'instructions', t.instructions, 'showResult', t.show_result, 'showAnswers', t.show_answers, 'sections', t.sections)
$$;

create or replace function public.cbt_state_json(a public.cbt_attempts)
returns jsonb language sql stable as $$
  select jsonb_build_object('id', a.id, 'state', a.state, 'startedAt', a.started_at, 'savedAt', a.saved_at, 'submittedAt', a.submitted_at,
    'serverNow', now(), 'answers', a.answers, 'marked', a.marked, 'current', a.current_no, 'lang', a.lang, 'switches', a.switches,
    'autoSubmitted', a.auto_submitted)
$$;

-- What a candidate may see after submitting: the score (if the test shows it), the key and their answers (if it shows answers).
create or replace function public.cbt_result_json(a public.cbt_attempts, t public.cbt_tests)
returns jsonb
language plpgsql
stable
as $$
declare k jsonb;
begin
  select answers into k from public.cbt_keys where test_id = t.id;
  return jsonb_build_object(
    'attempt', public.cbt_state_json(a),
    'showResult', t.show_result, 'showAnswers', t.show_answers,
    'score', case when t.show_result then a.score else null end,
    'answers', case when t.show_result then a.answers else null end,
    'key', case when t.show_result and t.show_answers then coalesce(k, '{}'::jsonb) else null end,
    'test', case when t.show_result and t.show_answers then public.cbt_paper(t) else null end);
end $$;

create or replace function public.cbt_finish(p_attempt text, p_answers jsonb, p_marked jsonb, p_switches int, p_auto boolean)
returns public.cbt_attempts
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests; k jsonb; within boolean; final_answers jsonb;
begin
  select * into a from public.cbt_attempts where id = p_attempt for update;
  select * into t from public.cbt_tests where id = a.test_id;
  if a.state = 'submitted' then return a; end if;
  within := now() <= public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second');
  final_answers := case when within and p_answers is not null then p_answers else a.answers end;
  select answers into k from public.cbt_keys where test_id = t.id;
  update public.cbt_attempts set
    answers = final_answers,
    marked = case when within and p_marked is not null then p_marked else marked end,
    switches = greatest(switches, coalesce(p_switches, 0)),
    state = 'submitted',
    submitted_at = least(now(), public.cbt_deadline(a, t)),
    saved_at = now(),
    auto_submitted = p_auto or not within,
    score = public.cbt_grade(t.sections, t.marking, coalesce(k, '{}'::jsonb), final_answers)
  where id = a.id returning * into a;
  return a;
end $$;

-- ── what candidates call ─────────────────────────────────────────────────────
-- Public facts about an exam (no questions): for the landing page.
create or replace function public.cbt_exam_info(p_test text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare t public.cbt_tests; st text;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status = 'draft' then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  st := case when t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at) then 'closed'
             when t.opens_at is not null and now() < t.opens_at then 'not_open' else 'open' end;
  return jsonb_build_object('id', t.id, 'name', t.name, 'durationMin', t.duration_min, 'marking', t.marking, 'instructions', t.instructions,
    'needsCode', coalesce(btrim(t.access_code), '') <> '', 'state', st, 'opensAt', t.opens_at, 'closesAt', t.closes_at, 'serverNow', now(),
    'sections', (select coalesce(jsonb_agg(jsonb_build_object('id', s ->> 'id', 'label', s ->> 'label', 'title', s ->> 'title',
        'count', jsonb_array_length(s -> 'questions'), 'first', (s -> 'questions' -> 0 ->> 'no')::int, 'last', (s -> 'questions' -> -1 ->> 'no')::int)), '[]'::jsonb)
      from jsonb_array_elements(t.sections) s));
end $$;

create or replace function public.cbt_start(p_test text, p_code text, p_name text, p_roll text, p_phone text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; a public.cbt_attempts; tok text;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status = 'draft' then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-CLOSED: This exam is closed.'; end if;
  if t.opens_at is not null and now() < t.opens_at then raise exception 'EXAM-NOT-OPEN: This exam has not opened yet.'; end if;
  if coalesce(btrim(t.access_code), '') <> '' and lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    raise exception 'EXAM-CODE: The access code is not correct.';
  end if;
  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(p_name)) > 80 then raise exception 'EXAM-INPUT: Enter your full name.'; end if;
  if length(btrim(coalesce(p_roll, ''))) < 1 or length(btrim(p_roll)) > 40 then raise exception 'EXAM-INPUT: Enter your roll or registration number.'; end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  begin
    insert into public.cbt_attempts (test_id, candidate_name, roll, phone, token)
    values (t.id, btrim(p_name), btrim(p_roll), nullif(left(btrim(coalesce(p_phone, '')), 20), ''), tok) returning * into a;
  exception when unique_violation then
    raise exception 'EXAM-DUP: This roll number has already started the exam. Open the exam on the same device to continue, or ask the institute to reset it.';
  end;
  return jsonb_build_object('token', tok, 'attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

create or replace function public.cbt_resume(p_attempt text, p_token text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found. Ask the institute to reset it.'; end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if a.state = 'inprogress' and now() > public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second') then
    a := public.cbt_finish(a.id, null, null, null, true);
  end if;
  if a.state = 'submitted' then return jsonb_build_object('result', public.cbt_result_json(a, t)); end if;
  return jsonb_build_object('attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

create or replace function public.cbt_save(p_attempt text, p_token text, p_answers jsonb, p_marked jsonb, p_current int, p_lang text, p_switches int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found.'; end if;
  if a.state = 'submitted' then return jsonb_build_object('submitted', true, 'serverNow', now()); end if;
  if octet_length(coalesce(p_answers, '{}'::jsonb)::text) > 20000 or octet_length(coalesce(p_marked, '{}'::jsonb)::text) > 20000 then
    raise exception 'EXAM-INPUT: Too much data.';
  end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if now() > public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second') then
    a := public.cbt_finish(a.id, null, null, p_switches, true);
    return jsonb_build_object('submitted', true, 'serverNow', now());
  end if;
  update public.cbt_attempts set answers = coalesce(p_answers, answers), marked = coalesce(p_marked, marked), current_no = coalesce(p_current, current_no),
    lang = coalesce(p_lang, lang), switches = greatest(switches, coalesce(p_switches, 0)), saved_at = now() where id = a.id;
  return jsonb_build_object('submitted', false, 'serverNow', now(), 'savedAt', now());
end $$;

create or replace function public.cbt_submit(p_attempt text, p_token text, p_answers jsonb, p_marked jsonb, p_switches int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found.'; end if;
  if octet_length(coalesce(p_answers, '{}'::jsonb)::text) > 20000 then raise exception 'EXAM-INPUT: Too much data.'; end if;
  a := public.cbt_finish(a.id, p_answers, p_marked, p_switches, false);
  select * into t from public.cbt_tests where id = a.test_id;
  return public.cbt_result_json(a, t);
end $$;

-- Only the functions candidates call are open to everyone; the helpers are internal.
revoke all on function public.cbt_grade(jsonb, jsonb, jsonb, jsonb) from public;
revoke all on function public.cbt_finish(text, jsonb, jsonb, int, boolean) from public;
revoke all on function public.cbt_result_json(public.cbt_attempts, public.cbt_tests) from public;
revoke all on function public.cbt_exam_info(text) from public;
revoke all on function public.cbt_start(text, text, text, text, text) from public;
revoke all on function public.cbt_resume(text, text) from public;
revoke all on function public.cbt_save(text, text, jsonb, jsonb, int, text, int) from public;
revoke all on function public.cbt_submit(text, text, jsonb, jsonb, int) from public;
grant execute on function public.cbt_exam_info(text) to anon, authenticated;
grant execute on function public.cbt_start(text, text, text, text, text) to anon, authenticated;
grant execute on function public.cbt_resume(text, text) to anon, authenticated;
grant execute on function public.cbt_save(text, text, jsonb, jsonb, int, text, int) to anon, authenticated;
grant execute on function public.cbt_submit(text, text, jsonb, jsonb, int) to anon, authenticated;

-- ───── 20261035_cbt_erp_lookup.sql ─────
-- ─────────────────────────────────────────────────────────────────────────────
-- Online exam: recognise the candidate from the ERP student list.
--   • cbt_lookup  — a candidate types their name or GCC no.; matching active students come back
--                   (name, class, GCC, masked parent phone). Only works for a valid exam link that has an
--                   access code, so the student list cannot be browsed by strangers.
--   • cbt_start   — now also stores the GCC no. and the parent's contact number, and flags whether the GCC no.
--                   exists in the ERP. If the parent number is left blank it is taken from the ERP record.
-- Run after 20261034_cbt_online_exam.sql.
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.cbt_attempts add column if not exists gcc_no text;
alter table public.cbt_attempts add column if not exists parent_phone text;
alter table public.cbt_attempts add column if not exists erp_match boolean not null default false;

create or replace function public.cbt_digits(p text) returns text language sql immutable as $$
  select right(regexp_replace(coalesce(p, ''), '\D', '', 'g'), 10) $$;

create or replace function public.cbt_student_phone(j jsonb) returns text language sql immutable as $$
  select public.cbt_digits(coalesce(nullif(btrim(j ->> 'parent_phone'), ''), nullif(btrim(j ->> 'father_phone'), ''),
    nullif(btrim(j ->> 'mother_phone'), ''), nullif(btrim(j ->> 'guardian_phone'), ''), nullif(btrim(j ->> 'guardian_mobile'), ''),
    nullif(btrim(j ->> 'parent_contact'), ''), nullif(btrim(j ->> 'mobile'), ''), nullif(btrim(j ->> 'phone'), ''))) $$;

create or replace function public.cbt_lookup(p_test text, p_code text, p_q text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; q text := btrim(coalesce(p_q, '')); g text; res jsonb;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status in ('draft', 'closed') or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if coalesce(btrim(t.access_code), '') = '' or lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    raise exception 'EXAM-CODE: Enter the access code first.';
  end if;
  if length(q) < 1 or (q !~ '^[0-9 ]+$' and length(q) < 3) then return '[]'::jsonb; end if;   -- a GCC no. is matched exactly; a name needs 3+ letters
  g := ltrim(regexp_replace(q, '\D', '', 'g'), '0');
  select coalesce(jsonb_agg(x), '[]'::jsonb) into res from (
    select jsonb_build_object('name', s.name, 'gcc', s.gcc_no::text,
             'className', coalesce(nullif(to_jsonb(s) ->> 'batch', ''), to_jsonb(s) ->> 'class_name', ''),
             'phoneHint', case when length(public.cbt_student_phone(to_jsonb(s))) >= 4 then '••••••' || right(public.cbt_student_phone(to_jsonb(s)), 4) else '' end) as x
    from public.students s
    where coalesce(s.status, 'Active') = 'Active'
      and ((g <> '' and q ~ '^[0-9 ]+$' and ltrim(s.gcc_no::text, '0') = g) or (q !~ '^[0-9 ]+$' and s.name ilike '%' || replace(replace(q, '%', ''), '_', '') || '%'))
    order by s.name limit 6) m;
  return res;
end $$;

drop function if exists public.cbt_start(text, text, text, text, text);
create or replace function public.cbt_start(p_test text, p_code text, p_name text, p_roll text, p_phone text default null,
                                            p_gcc text default null, p_parent text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; a public.cbt_attempts; tok text; st public.students; gcc text := nullif(btrim(coalesce(p_gcc, '')), ''); par text := public.cbt_digits(p_parent); hit boolean := false;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status = 'draft' then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-CLOSED: This exam is closed.'; end if;
  if t.opens_at is not null and now() < t.opens_at then raise exception 'EXAM-NOT-OPEN: This exam has not opened yet.'; end if;
  if coalesce(btrim(t.access_code), '') <> '' and lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    raise exception 'EXAM-CODE: The access code is not correct.';
  end if;
  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(p_name)) > 80 then raise exception 'EXAM-INPUT: Enter your full name.'; end if;
  if length(btrim(coalesce(p_roll, ''))) < 1 or length(btrim(p_roll)) > 40 then raise exception 'EXAM-INPUT: Enter your roll or registration number.'; end if;
  if length(par) < 10 then par := ''; end if;
  if gcc is not null then
    gcc := left(gcc, 20);
    select * into st from public.students s where ltrim(s.gcc_no::text, '0') = ltrim(gcc, '0') limit 1;
    hit := found;
    if hit and par = '' then par := public.cbt_student_phone(to_jsonb(st)); end if;
  end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  begin
    insert into public.cbt_attempts (test_id, candidate_name, roll, phone, gcc_no, parent_phone, erp_match, token)
    values (t.id, btrim(p_name), btrim(p_roll), nullif(left(btrim(coalesce(p_phone, '')), 20), ''), gcc, nullif(par, ''), hit, tok) returning * into a;
  exception when unique_violation then
    raise exception 'EXAM-DUP: This roll number has already started the exam. Open the exam on the same device to continue, or ask the institute to reset it.';
  end;
  return jsonb_build_object('token', tok, 'attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

revoke all on function public.cbt_lookup(text, text, text) from public;
revoke all on function public.cbt_start(text, text, text, text, text, text, text) from public;
grant execute on function public.cbt_lookup(text, text, text) to anon, authenticated;
grant execute on function public.cbt_start(text, text, text, text, text, text, text) to anon, authenticated;

-- ───── 20261036_cbt_lock_answers.sql ─────
-- ─────────────────────────────────────────────────────────────────────────────
-- Online exam: "Lock answers". When a test has marking.lock = true, an answer already saved on the server cannot be
-- changed or removed by a later save or by the final submit (the saved answer wins), so editing the page in the
-- browser cannot get around the lock. Run after 20261034_cbt_online_exam.sql.
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.cbt_finish(p_attempt text, p_answers jsonb, p_marked jsonb, p_switches int, p_auto boolean)
returns public.cbt_attempts
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests; k jsonb; within boolean; final_answers jsonb;
begin
  select * into a from public.cbt_attempts where id = p_attempt for update;
  select * into t from public.cbt_tests where id = a.test_id;
  if a.state = 'submitted' then return a; end if;
  within := now() <= public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second');
  final_answers := case when within and p_answers is not null then (case when coalesce((t.marking ->> 'lock')::boolean, false) then p_answers || a.answers else p_answers end) else a.answers end;
  select answers into k from public.cbt_keys where test_id = t.id;
  update public.cbt_attempts set
    answers = final_answers,
    marked = case when within and p_marked is not null then p_marked else marked end,
    switches = greatest(switches, coalesce(p_switches, 0)),
    state = 'submitted',
    submitted_at = least(now(), public.cbt_deadline(a, t)),
    saved_at = now(),
    auto_submitted = p_auto or not within,
    score = public.cbt_grade(t.sections, t.marking, coalesce(k, '{}'::jsonb), final_answers)
  where id = a.id returning * into a;
  return a;
end $$;

create or replace function public.cbt_save(p_attempt text, p_token text, p_answers jsonb, p_marked jsonb, p_current int, p_lang text, p_switches int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found.'; end if;
  if a.state = 'submitted' then return jsonb_build_object('submitted', true, 'serverNow', now()); end if;
  if octet_length(coalesce(p_answers, '{}'::jsonb)::text) > 20000 or octet_length(coalesce(p_marked, '{}'::jsonb)::text) > 20000 then
    raise exception 'EXAM-INPUT: Too much data.';
  end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if now() > public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second') then
    a := public.cbt_finish(a.id, null, null, p_switches, true);
    return jsonb_build_object('submitted', true, 'serverNow', now());
  end if;
  update public.cbt_attempts set answers = case when p_answers is null then answers when coalesce((t.marking ->> 'lock')::boolean, false) then p_answers || answers else p_answers end, marked = coalesce(p_marked, marked), current_no = coalesce(p_current, current_no),
    lang = coalesce(p_lang, lang), switches = greatest(switches, coalesce(p_switches, 0)), saved_at = now() where id = a.id;
  return jsonb_build_object('submitted', false, 'serverNow', now(), 'savedAt', now());
end $$;

-- ───── 20261037_cbt_hardening.sql ─────
-- ─────────────────────────────────────────────────────────────────────────────
-- Online exam hardening (run after 20261034, 20261035 and 20261036). Closes these loopholes:
--   1. The answer key / review was shown the moment a candidate submitted — someone could submit blank and pass the
--      key to friends still sitting the exam. It is now released only after the exam has closed AND nobody is still
--      inside their time (cbt_answers_open). The score is shown as before.
--   2. A second attempt under another roll no. or GCC no. (to see the paper first): one attempt per GCC no. now.
--   3. Guessing the access code, or reading the student list through the name finder, was unlimited: now limited per
--      network address (30 wrong codes / 60 finder searches per 10 minutes).
--   4. Claiming another student's GCC no.: the attempt is flagged unless the name matches the ERP record.
--   5. Junk in the saved answers: only question numbers with an A–D answer are kept.
--   6. Flooding a test with fake attempts: capped at 2000 attempts per test.
--   7. Helper functions were callable by anyone: now internal only.
-- ─────────────────────────────────────────────────────────────────────────────

-- ── limits per network address ──────────────────────────────────────────────
create table if not exists public.cbt_hits (
  id   bigserial primary key,
  ip   text not null,
  kind text not null,
  at   timestamptz not null default now()
);
create index if not exists cbt_hits_ip_idx on public.cbt_hits (ip, kind, at);
alter table public.cbt_hits enable row level security;   -- no policy: only the functions below touch it

create or replace function public.cbt_client_ip() returns text
language plpgsql stable as $$
declare h jsonb;
begin
  begin h := nullif(current_setting('request.headers', true), '')::jsonb; exception when others then h := null; end;
  return coalesce(nullif(btrim(split_part(coalesce(h ->> 'x-forwarded-for', h ->> 'x-real-ip', ''), ',', 1)), ''), 'unknown');
end $$;

create or replace function public.cbt_throttled(p_kind text, p_max int) returns boolean
language sql security definer set search_path = public as $$
  select count(*) >= p_max from public.cbt_hits h where h.ip = public.cbt_client_ip() and h.kind = p_kind and h.at > now() - interval '10 minutes'
$$;

create or replace function public.cbt_hit(p_kind text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if random() < 0.02 then delete from public.cbt_hits where at < now() - interval '1 day'; end if;
  insert into public.cbt_hits (ip, kind) values (public.cbt_client_ip(), p_kind);
end $$;

-- ── answers: only question numbers with A–D ─────────────────────────────────
create or replace function public.cbt_clean_answers(p jsonb) returns jsonb
language sql immutable as $$
  select case when p is null or jsonb_typeof(p) <> 'object' then '{}'::jsonb else
    coalesce((select jsonb_object_agg(key, value) from jsonb_each(p)
              where key ~ '^[0-9]{1,4}$' and jsonb_typeof(value) = 'string' and (value #>> '{}') in ('A', 'B', 'C', 'D')), '{}'::jsonb) end
$$;

-- ── one attempt per GCC no. ─────────────────────────────────────────────────
alter table public.cbt_attempts add column if not exists gcc_key text
  generated always as (nullif(ltrim(regexp_replace(coalesce(gcc_no, ''), '\D', '', 'g'), '0'), '')) stored;
create unique index if not exists cbt_attempts_gcc_once on public.cbt_attempts (test_id, gcc_key) where gcc_key is not null;

-- ── may the key be shown yet? exam closed and nobody still inside their time ─
create or replace function public.cbt_answers_open(t public.cbt_tests) returns boolean
language sql stable security definer set search_path = public as $$
  select (t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at))
     and not exists (select 1 from public.cbt_attempts x
                     where x.test_id = t.id and x.state = 'inprogress'
                       and now() <= x.started_at + (t.duration_min * interval '1 minute') + (t.grace_seconds * interval '1 second'))
$$;

create or replace function public.cbt_result_json(a public.cbt_attempts, t public.cbt_tests)
returns jsonb
language plpgsql
stable
as $$
declare k jsonb; open boolean := public.cbt_answers_open(t);
begin
  select answers into k from public.cbt_keys where test_id = t.id;
  return jsonb_build_object(
    'attempt', public.cbt_state_json(a),
    'showResult', t.show_result, 'showAnswers', t.show_answers,
    'answersLater', t.show_result and t.show_answers and not open,
    'score', case when t.show_result then a.score else null end,
    'answers', case when t.show_result then a.answers else null end,
    'key', case when t.show_result and t.show_answers and open then coalesce(k, '{}'::jsonb) else null end,
    'test', case when t.show_result and t.show_answers and open then public.cbt_paper(t) else null end);
end $$;

-- ── save / finish: cleaned answers, and the lock from 20261036 ───────────────
create or replace function public.cbt_finish(p_attempt text, p_answers jsonb, p_marked jsonb, p_switches int, p_auto boolean)
returns public.cbt_attempts
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests; k jsonb; within boolean; final_answers jsonb;
begin
  select * into a from public.cbt_attempts where id = p_attempt for update;
  select * into t from public.cbt_tests where id = a.test_id;
  if a.state = 'submitted' then return a; end if;
  within := now() <= public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second');
  final_answers := case when within and p_answers is not null then (case when coalesce((t.marking ->> 'lock')::boolean, false) then public.cbt_clean_answers(p_answers) || a.answers else public.cbt_clean_answers(p_answers) end) else a.answers end;
  select answers into k from public.cbt_keys where test_id = t.id;
  update public.cbt_attempts set
    answers = final_answers,
    marked = case when within and p_marked is not null then p_marked else marked end,
    switches = greatest(switches, coalesce(p_switches, 0)),
    state = 'submitted',
    submitted_at = least(now(), public.cbt_deadline(a, t)),
    saved_at = now(),
    auto_submitted = p_auto or not within,
    score = public.cbt_grade(t.sections, t.marking, coalesce(k, '{}'::jsonb), final_answers)
  where id = a.id returning * into a;
  return a;
end $$;

create or replace function public.cbt_save(p_attempt text, p_token text, p_answers jsonb, p_marked jsonb, p_current int, p_lang text, p_switches int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found.'; end if;
  if a.state = 'submitted' then return jsonb_build_object('submitted', true, 'serverNow', now()); end if;
  if octet_length(coalesce(p_answers, '{}'::jsonb)::text) > 20000 or octet_length(coalesce(p_marked, '{}'::jsonb)::text) > 20000 then
    raise exception 'EXAM-INPUT: Too much data.';
  end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if now() > public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second') then
    a := public.cbt_finish(a.id, null, null, p_switches, true);
    return jsonb_build_object('submitted', true, 'serverNow', now());
  end if;
  update public.cbt_attempts set answers = case when p_answers is null then answers else (case when coalesce((t.marking ->> 'lock')::boolean, false) then public.cbt_clean_answers(p_answers) || answers else public.cbt_clean_answers(p_answers) end) end, marked = coalesce(p_marked, marked), current_no = coalesce(p_current, current_no),
    lang = coalesce(p_lang, lang), switches = greatest(switches, coalesce(p_switches, 0)), saved_at = now() where id = a.id;
  return jsonb_build_object('submitted', false, 'serverNow', now(), 'savedAt', now());
end $$;

-- ── the name finder: limited, errors returned (a raised error would undo the count) ──
create or replace function public.cbt_lookup(p_test text, p_code text, p_q text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; q text := btrim(coalesce(p_q, '')); g text; res jsonb;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status in ('draft', 'closed') or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if public.cbt_throttled('find', 60) or public.cbt_throttled('code', 30) then
    return jsonb_build_object('error', 'EXAM-LIMIT: Too many searches from this network. Wait ten minutes and try again, or type your details.');
  end if;
  if coalesce(btrim(t.access_code), '') = '' or lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    perform public.cbt_hit('code');
    return jsonb_build_object('error', 'EXAM-CODE: Enter the access code first.');
  end if;
  perform public.cbt_hit('find');
  if length(q) < 1 or (q !~ '^[0-9 ]+$' and length(q) < 3) then return '[]'::jsonb; end if;
  g := ltrim(regexp_replace(q, '\D', '', 'g'), '0');
  select coalesce(jsonb_agg(x), '[]'::jsonb) into res from (
    select jsonb_build_object('name', s.name, 'gcc', s.gcc_no::text,
             'className', coalesce(nullif(to_jsonb(s) ->> 'batch', ''), to_jsonb(s) ->> 'class_name', ''),
             'phoneHint', case when length(public.cbt_student_phone(to_jsonb(s))) >= 4 then '••••••' || right(public.cbt_student_phone(to_jsonb(s)), 4) else '' end) as x
    from public.students s
    where coalesce(s.status, 'Active') = 'Active'
      and ((g <> '' and q ~ '^[0-9 ]+$' and ltrim(s.gcc_no::text, '0') = g) or (q !~ '^[0-9 ]+$' and s.name ilike '%' || replace(replace(q, '%', ''), '_', '') || '%'))
    order by s.name limit 6) m;
  return res;
end $$;

-- ── start: limits, the 2000 cap, name check against the ERP ─────────────────
create or replace function public.cbt_start(p_test text, p_code text, p_name text, p_roll text, p_phone text default null,
                                            p_gcc text default null, p_parent text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; a public.cbt_attempts; tok text; st public.students; gcc text := nullif(btrim(coalesce(p_gcc, '')), '');
        par text := public.cbt_digits(p_parent); hit boolean := false;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status = 'draft' then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-CLOSED: This exam is closed.'; end if;
  if t.opens_at is not null and now() < t.opens_at then raise exception 'EXAM-NOT-OPEN: This exam has not opened yet.'; end if;
  if public.cbt_throttled('code', 30) then
    return jsonb_build_object('error', 'EXAM-LIMIT: Too many wrong codes from this network. Wait ten minutes and try again.');
  end if;
  if coalesce(btrim(t.access_code), '') <> '' and lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    perform public.cbt_hit('code');
    return jsonb_build_object('error', 'EXAM-CODE: The access code is not correct.');
  end if;
  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(p_name)) > 80 then raise exception 'EXAM-INPUT: Enter your full name.'; end if;
  if length(btrim(coalesce(p_roll, ''))) < 1 or length(btrim(p_roll)) > 40 then raise exception 'EXAM-INPUT: Enter your roll or registration number.'; end if;
  if (select count(*) from public.cbt_attempts where test_id = t.id) >= 2000 then raise exception 'EXAM-FULL: This exam has reached its limit of candidates. Ask the institute.'; end if;
  if length(par) < 10 then par := ''; end if;
  if gcc is not null then
    gcc := left(gcc, 20);
    select * into st from public.students s where ltrim(s.gcc_no::text, '0') = ltrim(gcc, '0') limit 1;
    -- matched only when the typed name is the ERP name too, so using a classmate's GCC no. shows up as a flag
    hit := found and regexp_replace(lower(st.name), '[^[:alnum:]]+', '', 'g') = regexp_replace(lower(p_name), '[^[:alnum:]]+', '', 'g');
    if found and par = '' then par := public.cbt_student_phone(to_jsonb(st)); end if;
  end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  begin
    insert into public.cbt_attempts (test_id, candidate_name, roll, phone, gcc_no, parent_phone, erp_match, token)
    values (t.id, btrim(p_name), btrim(p_roll), nullif(left(btrim(coalesce(p_phone, '')), 20), ''), gcc, nullif(par, ''), hit, tok) returning * into a;
  exception when unique_violation then
    raise exception 'EXAM-DUP: This roll number or GCC no. has already started the exam. Open the exam on the same device to continue, or ask the institute to reset it.';
  end;
  return jsonb_build_object('token', tok, 'attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

-- ── helpers are internal; the public functions stay open ─────────────────────
revoke all on function public.cbt_paper(public.cbt_tests) from public;
revoke all on function public.cbt_state_json(public.cbt_attempts) from public;
revoke all on function public.cbt_deadline(public.cbt_attempts, public.cbt_tests) from public;
revoke all on function public.cbt_digits(text) from public;
revoke all on function public.cbt_student_phone(jsonb) from public;
revoke all on function public.cbt_client_ip() from public;
revoke all on function public.cbt_throttled(text, int) from public;
revoke all on function public.cbt_hit(text) from public;
revoke all on function public.cbt_clean_answers(jsonb) from public;
revoke all on function public.cbt_answers_open(public.cbt_tests) from public;
revoke all on function public.cbt_result_json(public.cbt_attempts, public.cbt_tests) from public;
revoke all on function public.cbt_finish(text, jsonb, jsonb, int, boolean) from public;
revoke all on function public.cbt_lookup(text, text, text) from public;
revoke all on function public.cbt_start(text, text, text, text, text, text, text) from public;
revoke all on function public.cbt_save(text, text, jsonb, jsonb, int, text, int) from public;
grant execute on function public.cbt_lookup(text, text, text) to anon, authenticated;
grant execute on function public.cbt_start(text, text, text, text, text, text, text) to anon, authenticated;
grant execute on function public.cbt_save(text, text, jsonb, jsonb, int, text, int) to anon, authenticated;

-- ───── 20261038_cbt_integrity.sql ─────
-- ─────────────────────────────────────────────────────────────────────────────
-- Online exam: integrity features (run after 20261034–20261037).
--   • One device at a time: every attempt has a session id. Opening the exam again (another phone, another
--     browser, the copied link + token) takes the session over and the first screen is stopped with a message
--     (EXAM-SESSION); the takeovers are counted. A page reload on the same device is not a takeover.
--   • Network address at the start and at the last save, so staff can see candidates sharing one network or
--     changing network mid-exam.
--   • "Earliest submit": a test can set marking.minMinutes — the final submit is refused before that
--     (EXAM-EARLY), which stops submit-blank-and-leave. Time running out is never blocked.
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.cbt_attempts add column if not exists session   text;
alter table public.cbt_attempts add column if not exists takeovers int  not null default 0;
alter table public.cbt_attempts add column if not exists ip_start  text;
alter table public.cbt_attempts add column if not exists ip_last   text;

create or replace function public.cbt_start(p_test text, p_code text, p_name text, p_roll text, p_phone text default null,
                                            p_gcc text default null, p_parent text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; a public.cbt_attempts; tok text; st public.students; gcc text := nullif(btrim(coalesce(p_gcc, '')), '');
        par text := public.cbt_digits(p_parent); hit boolean := false; sess text := replace(gen_random_uuid()::text, '-', '');
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status = 'draft' then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-CLOSED: This exam is closed.'; end if;
  if t.opens_at is not null and now() < t.opens_at then raise exception 'EXAM-NOT-OPEN: This exam has not opened yet.'; end if;
  if public.cbt_throttled('code', 30) then
    return jsonb_build_object('error', 'EXAM-LIMIT: Too many wrong codes from this network. Wait ten minutes and try again.');
  end if;
  if coalesce(btrim(t.access_code), '') <> '' and lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    perform public.cbt_hit('code');
    return jsonb_build_object('error', 'EXAM-CODE: The access code is not correct.');
  end if;
  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(p_name)) > 80 then raise exception 'EXAM-INPUT: Enter your full name.'; end if;
  if length(btrim(coalesce(p_roll, ''))) < 1 or length(btrim(p_roll)) > 40 then raise exception 'EXAM-INPUT: Enter your roll or registration number.'; end if;
  if (select count(*) from public.cbt_attempts where test_id = t.id) >= 2000 then raise exception 'EXAM-FULL: This exam has reached its limit of candidates. Ask the institute.'; end if;
  if length(par) < 10 then par := ''; end if;
  if gcc is not null then
    gcc := left(gcc, 20);
    select * into st from public.students s where ltrim(s.gcc_no::text, '0') = ltrim(gcc, '0') limit 1;
    -- matched only when the typed name is the ERP name too, so using a classmate's GCC no. shows up as a flag
    hit := found and regexp_replace(lower(st.name), '[^[:alnum:]]+', '', 'g') = regexp_replace(lower(p_name), '[^[:alnum:]]+', '', 'g');
    if found and par = '' then par := public.cbt_student_phone(to_jsonb(st)); end if;
  end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  begin
    insert into public.cbt_attempts (test_id, candidate_name, roll, phone, gcc_no, parent_phone, erp_match, token, session, ip_start, ip_last)
    values (t.id, btrim(p_name), btrim(p_roll), nullif(left(btrim(coalesce(p_phone, '')), 20), ''), gcc, nullif(par, ''), hit, tok, sess, public.cbt_client_ip(), public.cbt_client_ip()) returning * into a;
  exception when unique_violation then
    raise exception 'EXAM-DUP: This roll number or GCC no. has already started the exam. Open the exam on the same device to continue, or ask the institute to reset it.';
  end;
  return jsonb_build_object('token', tok, 'session', sess, 'attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

drop function if exists public.cbt_save(text, text, jsonb, jsonb, int, text, int);
create or replace function public.cbt_save(p_attempt text, p_token text, p_answers jsonb, p_marked jsonb, p_current int, p_lang text, p_switches int, p_session text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found.'; end if;
  if a.state = 'submitted' then return jsonb_build_object('submitted', true, 'serverNow', now()); end if;
  if a.session is distinct from p_session then raise exception 'EXAM-SESSION: This exam was opened on another device or window. Only one can run an attempt — this one has stopped.'; end if;
  if octet_length(coalesce(p_answers, '{}'::jsonb)::text) > 20000 or octet_length(coalesce(p_marked, '{}'::jsonb)::text) > 20000 then
    raise exception 'EXAM-INPUT: Too much data.';
  end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if now() > public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second') then
    a := public.cbt_finish(a.id, null, null, p_switches, true);
    return jsonb_build_object('submitted', true, 'serverNow', now());
  end if;
  update public.cbt_attempts set answers = case when p_answers is null then answers else (case when coalesce((t.marking ->> 'lock')::boolean, false) then public.cbt_clean_answers(p_answers) || answers else public.cbt_clean_answers(p_answers) end) end, marked = coalesce(p_marked, marked), current_no = coalesce(p_current, current_no),
    lang = coalesce(p_lang, lang), switches = greatest(switches, coalesce(p_switches, 0)), saved_at = now(), ip_last = public.cbt_client_ip() where id = a.id;
  return jsonb_build_object('submitted', false, 'serverNow', now(), 'savedAt', now());
end $$;

drop function if exists public.cbt_resume(text, text);
create or replace function public.cbt_resume(p_attempt text, p_token text, p_session text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests; sess text;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found. Ask the institute to reset it.'; end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if a.state = 'inprogress' and now() > public.cbt_deadline(a, t) + (t.grace_seconds * interval '1 second') then
    a := public.cbt_finish(a.id, null, null, null, true);
  end if;
  if a.state = 'submitted' then return jsonb_build_object('result', public.cbt_result_json(a, t)); end if;
  -- the same device reopening keeps its session; any other device takes the attempt over
  if a.session is not distinct from p_session and p_session is not null then
    sess := a.session;
  else
    sess := replace(gen_random_uuid()::text, '-', '');
    update public.cbt_attempts set session = sess, takeovers = takeovers + (case when a.session is null then 0 else 1 end),
      ip_last = public.cbt_client_ip() where id = a.id returning * into a;
  end if;
  return jsonb_build_object('session', sess, 'attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

drop function if exists public.cbt_submit(text, text, jsonb, jsonb, int);
create or replace function public.cbt_submit(p_attempt text, p_token text, p_answers jsonb, p_marked jsonb, p_switches int, p_session text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare a public.cbt_attempts; t public.cbt_tests; early numeric;
begin
  select * into a from public.cbt_attempts where id = p_attempt and token = p_token;
  if not found then raise exception 'EXAM-TOKEN: This attempt could not be found.'; end if;
  select * into t from public.cbt_tests where id = a.test_id;
  if a.state = 'submitted' then return public.cbt_result_json(a, t); end if;
  if a.session is distinct from p_session then raise exception 'EXAM-SESSION: This exam was opened on another device or window. Only one can run an attempt — this one has stopped.'; end if;
  if octet_length(coalesce(p_answers, '{}'::jsonb)::text) > 20000 then raise exception 'EXAM-INPUT: Too much data.'; end if;
  early := coalesce((t.marking ->> 'minMinutes')::numeric, 0);
  if early > 0 and now() < a.started_at + (early * interval '1 minute') and now() <= public.cbt_deadline(a, t) then
    raise exception 'EXAM-EARLY: You can submit only after % minutes. Keep going until then.', early;
  end if;
  a := public.cbt_finish(a.id, p_answers, p_marked, p_switches, false);
  return public.cbt_result_json(a, t);
end $$;

revoke all on function public.cbt_resume(text, text, text) from public;
revoke all on function public.cbt_submit(text, text, jsonb, jsonb, int, text) from public;
revoke all on function public.cbt_save(text, text, jsonb, jsonb, int, text, int, text) from public;
revoke all on function public.cbt_start(text, text, text, text, text, text, text) from public;
grant execute on function public.cbt_resume(text, text, text) to anon, authenticated;
grant execute on function public.cbt_submit(text, text, jsonb, jsonb, int, text) to anon, authenticated;
grant execute on function public.cbt_save(text, text, jsonb, jsonb, int, text, int, text) to anon, authenticated;
grant execute on function public.cbt_start(text, text, text, text, text, text, text) to anon, authenticated;

-- ───── 20261039_cbt_gcc_identity.sql ─────
-- ─────────────────────────────────────────────────────────────────────────────
-- Online exam: the candidate is identified by GCC no. only (run after 20261034–20261038).
--   • The candidate types the access code and their GCC no.; the name and class come from the ERP student record
--     (no free-typed name or roll no. any more — the roll no. is the GCC no.).
--   • They must also type a parent / guardian contact number that matches a number on the ERP record. A hint shows
--     the last four digits of the number on file. Wrong numbers are limited (10 per GCC no. and 15 per network
--     every 10 minutes). A student with no number on file can still start; the attempt is marked "not verified".
--   • The finder no longer searches by name — a GCC no. is matched exactly — so the student list cannot be browsed.
--   • The old cbt_start / cbt_lookup (free-typed name) are removed so they cannot be used to get round this.
--   • Re-runnable, and it also repairs a database where only 20261040 was run (two cbt_lookup versions → "could not
--     choose the best candidate function"): the old 3-argument cbt_lookup is dropped here.
-- ─────────────────────────────────────────────────────────────────────────────

alter table public.cbt_attempts add column if not exists phone_verified boolean not null default false;

-- every 10-digit number on a student record (parent, father, mother, guardian …)
create or replace function public.cbt_student_phones(j jsonb) returns text[]
language sql immutable as $$
  select coalesce(array_agg(distinct d) filter (where length(d) = 10), '{}'::text[]) from (
    select public.cbt_digits(j ->> k) as d
    from unnest(array['parent_phone', 'father_phone', 'mother_phone', 'guardian_phone', 'guardian_mobile', 'parent_contact', 'whatsapp_no', 'mobile', 'phone']) k) x
$$;

drop function if exists public.cbt_lookup(text, text, text);
create or replace function public.cbt_lookup(p_test text, p_code text, p_q text, p_parent text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; g text := ltrim(regexp_replace(coalesce(p_q, ''), '\D', '', 'g'), '0'); st public.students; phones text[]; par text := public.cbt_digits(p_parent); ok boolean;
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status in ('draft', 'closed') or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if public.cbt_throttled('find', 60) or public.cbt_throttled('code', 30) or public.cbt_throttled('phone', 15) then
    return jsonb_build_object('error', 'EXAM-LIMIT: Too many tries from this network. Wait ten minutes and try again.');
  end if;
  if coalesce(btrim(t.access_code), '') = '' or lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    perform public.cbt_hit('code');
    return jsonb_build_object('error', 'EXAM-CODE: Enter the correct access code first.');
  end if;
  perform public.cbt_hit('find');
  if g = '' or length(g) > 12 then return '[]'::jsonb; end if;
  select * into st from public.students s where ltrim(s.gcc_no::text, '0') = g and coalesce(s.status, 'Active') = 'Active' limit 1;
  if not found then return '[]'::jsonb; end if;
  phones := public.cbt_student_phones(to_jsonb(st));
  if p_parent is not null then
    if (select count(*) from public.cbt_hits h where h.kind = 'phone:' || g and h.at > now() - interval '10 minutes') >= 10 then
      return jsonb_build_object('error', 'EXAM-LIMIT: Too many wrong numbers for this GCC no. Wait ten minutes and try again, or ask the office.');
    end if;
    ok := case when cardinality(phones) = 0 then null else par = any (phones) end;
    if ok is false then
      perform public.cbt_hit('phone');
      insert into public.cbt_hits (ip, kind) values ('*', 'phone:' || g);
    end if;
  end if;
  return jsonb_build_array(jsonb_build_object('name', st.name, 'gcc', st.gcc_no::text,
    'className', coalesce(nullif(to_jsonb(st) ->> 'batch', ''), to_jsonb(st) ->> 'class_name', ''),
    'phoneHint', case when cardinality(phones) > 0 then '••••••' || right(phones[1], 4) else '' end,
    'fatherName', coalesce(nullif(btrim(to_jsonb(st) ->> 'father_name'), ''), ''),
    'hasPhone', cardinality(phones) > 0,
    'verified', case when p_parent is null then null else ok end));
end $$;

drop function if exists public.cbt_start(text, text, text, text, text, text, text);
create or replace function public.cbt_start(p_test text, p_code text, p_gcc text, p_parent text default null, p_phone text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare t public.cbt_tests; a public.cbt_attempts; tok text; st public.students; g text := ltrim(regexp_replace(coalesce(p_gcc, ''), '\D', '', 'g'), '0');
        par text := public.cbt_digits(p_parent); phones text[]; ok boolean; sess text := replace(gen_random_uuid()::text, '-', '');
begin
  select * into t from public.cbt_tests where id = p_test;
  if not found or t.status = 'draft' then raise exception 'EXAM-404: This exam link is not valid.'; end if;
  if t.status = 'closed' or (t.closes_at is not null and now() > t.closes_at) then raise exception 'EXAM-CLOSED: This exam is closed.'; end if;
  if t.opens_at is not null and now() < t.opens_at then raise exception 'EXAM-NOT-OPEN: This exam has not opened yet.'; end if;
  if public.cbt_throttled('code', 30) or public.cbt_throttled('phone', 15) or public.cbt_throttled('find', 60) then
    return jsonb_build_object('error', 'EXAM-LIMIT: Too many tries from this network. Wait ten minutes and try again.');
  end if;
  if coalesce(btrim(t.access_code), '') = '' or lower(btrim(coalesce(p_code, ''))) <> lower(btrim(t.access_code)) then
    perform public.cbt_hit('code');
    return jsonb_build_object('error', 'EXAM-CODE: The access code is not correct.');
  end if;
  if g = '' or length(g) > 12 then return jsonb_build_object('error', 'EXAM-GCC: Enter your GCC no.'); end if;
  select * into st from public.students s where ltrim(s.gcc_no::text, '0') = g and coalesce(s.status, 'Active') = 'Active' limit 1;
  if not found then
    perform public.cbt_hit('find');
    return jsonb_build_object('error', 'EXAM-GCC: This GCC no. was not found in the institute records. Check it, or ask the office.');
  end if;
  phones := public.cbt_student_phones(to_jsonb(st));
  if cardinality(phones) > 0 then
    if (select count(*) from public.cbt_hits h where h.kind = 'phone:' || g and h.at > now() - interval '10 minutes') >= 10 then
      return jsonb_build_object('error', 'EXAM-LIMIT: Too many wrong numbers for this GCC no. Wait ten minutes and try again, or ask the office.');
    end if;
    ok := par = any (phones);
    if not ok then
      perform public.cbt_hit('phone');
      insert into public.cbt_hits (ip, kind) values ('*', 'phone:' || g);
      return jsonb_build_object('error', 'EXAM-PHONE: This contact number does not match the one in the institute records. Use the parent / guardian number given at admission.');
    end if;
  end if;
  if (select count(*) from public.cbt_attempts where test_id = t.id) >= 2000 then raise exception 'EXAM-FULL: This exam has reached its limit of candidates. Ask the institute.'; end if;
  tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  begin
    insert into public.cbt_attempts (test_id, candidate_name, roll, phone, gcc_no, parent_phone, erp_match, phone_verified, token, session, ip_start, ip_last)
    values (t.id, btrim(st.name), g, nullif(left(btrim(coalesce(p_phone, '')), 20), ''), st.gcc_no::text, nullif(par, ''), true, cardinality(phones) > 0, tok, sess,
            public.cbt_client_ip(), public.cbt_client_ip()) returning * into a;
  exception when unique_violation then
    raise exception 'EXAM-DUP: This GCC no. has already started the exam. Open the exam on the same device to continue, or ask the institute to reset it.';
  end;
  return jsonb_build_object('token', tok, 'session', sess, 'attempt', public.cbt_state_json(a), 'test', public.cbt_paper(t));
end $$;

revoke all on function public.cbt_student_phones(jsonb) from public;
revoke all on function public.cbt_lookup(text, text, text, text) from public;
revoke all on function public.cbt_start(text, text, text, text, text) from public;
grant execute on function public.cbt_lookup(text, text, text, text) to anon, authenticated;
grant execute on function public.cbt_start(text, text, text, text, text) to anon, authenticated;

-- ───── 20261040_cbt_lookup_father.sql ─────
-- Online exam: the GCC lookup also returns the father's name, so the landing page can show it (read-only) next to the
-- name and class as another check that the candidate found themselves. Run AFTER 20261039_cbt_gcc_identity.sql
-- (which now includes this already — 20261040 is only kept so databases that ran the earlier 20261039 can catch up).

do $$ begin
  if not exists (select 1 from information_schema.columns where table_name = 'cbt_attempts' and column_name = 'phone_verified') then
    raise exception 'Run 20261039_cbt_gcc_identity.sql first, then this one.';
  end if;
end $$;

